<template>
 <div class="scene-rail-content">
  <div class="scene-mini-art" :style="{backgroundPosition:atmosphere.position}" aria-hidden="true" />
  <p class="rail-eyebrow">此间 · {{scene.storyTime || '山海之中'}}</p><h2>{{scene.locationName || '云幕将启'}}</h2>
  <section v-if="scene.sceneSummary || scene.openingCharacters?.length" class="rail-section"><details><summary>初至此地 · 当时记录</summary><p v-if="scene.sceneSummary">{{visibleText(scene.sceneSummary.split('【当前局势】')[0])}}</p><p v-for="person in scene.openingCharacters || []" :key="person.id"><strong>{{person.name}}</strong> · {{visibleText(person.introduction)}}</p></details></section>
  <section v-if="scene.playerPhysicalState" class="rail-section"><h3>你的状态</h3><p class="rail-self-body"><span>{{scene.playerPhysicalState.awake===false?'意识未恢复':'清醒'}}</span><span>{{scene.playerPhysicalState.bound?'受束缚':'未受束缚'}}</span></p><p class="rail-muted"><span v-if="knownPosition(scene.playerPhysicalState.position)">{{knownPosition(scene.playerPhysicalState.position)}} </span><template v-if="scene.playerPhysicalState.activity">{{scene.playerPhysicalState.activityHistorical?'此前记录：':'当前状态：'}}{{scene.playerPhysicalState.activity}}</template></p></section>
  <section class="rail-section"><h3>{{scene.presenceSource==='OBSERVED'?'最近所见人物':'初至所见人物'}} <small>{{people.length}}</small></h3><div v-if="people.length" class="rail-people"><button v-for="person in people" :key="person.godId" :disabled="busy" @click="emit('talk',person)"><span class="rail-person-sigil" aria-hidden="true">{{person.godName.slice(0,1)}}</span><span>{{person.godName}}<small>{{bodyLabel(person.godId)}}</small><small v-if="knownPosition(body(person.godId)?.position)">{{knownPosition(body(person.godId)?.position)}}</small></span><i aria-hidden="true">↗</i></button></div><p v-else class="rail-muted">尚无可指认的现场人物。</p><p v-if="scene.presenceSource==='OBSERVED' && people.length" class="rail-muted">记录你最近的所见，之后未感知的变化不会自动更新。</p></section>
  <section class="rail-section"><h3>可见动态</h3><ol v-if="visibleTimeline.length" class="rail-events"><li v-for="(event,i) in visibleTimeline.slice(-3)" :key="i"><small>{{event.time}}</small><p>{{sceneNote(event.text)}}</p></li></ol><p v-else class="rail-muted">当前没有新的可见动态，已发生经过见故事正文。</p></section>
  <section class="rail-section"><h3>已知出口</h3><button v-for="exit in scene.exits || []" :key="exit.direction" class="rail-exit" :disabled="busy" @click="emit('exit',exit)"><span>{{exit.exitName || direction(exit.direction)}}</span><span aria-hidden="true">→</span></button><p v-if="!scene.exits?.length" class="rail-muted">前路尚未探明，可以描述探索方向。</p></section>
  <section v-if="objectives.length" class="rail-section"><details class="rail-details"><summary>此身所求 <small>{{objectives.filter(o=>o.status==='ACTIVE').length}} 未竟</small></summary><div v-for="goal in objectives" :key="goal.objectiveId" class="rail-objective"><strong>{{goal.title}}</strong><small>{{goal.status==='COMPLETED'?'已成':goal.status==='FAILED'?'已败':'进行中'}} · {{goal.progress ?? 0}}%</small><progress :value="goal.progress ?? 0" max="100" :aria-label="`${goal.title}进度`" style="width:100%" /><p>{{visibleText(goal.currentStep || goal.description || '')}}</p></div></details></section>
  <section v-if="legacyRepair.available" class="rail-section"><p class="rail-muted">这份旧存档的开局目标使用了无法验证的认知条件，可查看替代方案后重订。</p><button :disabled="busy" @click="emit('repair-objectives')">查看重订开局目标</button></section>
  <section class="rail-section knowledge-notebook"><h3>见闻与约定 <small>{{scene.knowledge?.length || 0}}</small></h3>
   <label v-if="people.length" class="knowledge-recipient">交流对象<select :value="target" @change="emit('update:target',$event.target.value)"><option value="">选择人物</option><option v-for="person in people" :key="person.godId" :value="person.godId">{{person.godName}}</option></select></label>
   <details v-for="entry in scene.knowledge || []" :key="entry.knowledgeId" class="knowledge-entry"><summary><span>{{visibleText(entry.title)}}</span><small>{{sourceLabel(entry)}}</small></summary><p>{{visibleText(entry.content)}}</p><p v-if="entry.verificationNote" class="knowledge-verification">第{{entry.verifiedTick}}刻核验：{{visibleText(entry.verificationNote)}}</p><footer><small>{{entry.locationName}}<span v-if="entry.sourceName"> · {{entry.sourceName}}</span></small><div><button v-if="!['PROMISE','TREATY'].includes(entry.sourceType)" :disabled="busy || !target" @click="emit('share',entry)">向此人分享</button><button v-if="!['SOCIAL','PROMISE','TREATY'].includes(entry.sourceType)" :disabled="busy || !target" @click="emit('question',entry)">向此人求证</button><button v-if="entry.canVerify" :disabled="busy" @click="emit('verify',entry)">现场核验</button></div></footer></details>
   <p v-if="!scene.knowledge?.length" class="rail-muted">亲见与听闻，会在这里留下记录。</p>
   <div v-for="entry in (scene.knowledge || []).filter(k=>k.sourceType==='TREATY' && ['PROPOSED','ACTIVE'].includes(k.treaty?.status))" :key="`treaty-${entry.knowledgeId}`" class="knowledge-entry">
    <strong>{{visibleText(entry.title)}}</strong><p class="rail-muted">{{entry.treaty.status==='PROPOSED'?'提议尚待回应':'盟约已经生效'}}。以下操作只填入草稿，由你确认发送。</p>
    <template v-if="entry.treaty.status==='PROPOSED' && !entry.treaty.isProposer"><button :disabled="treatyUnavailable(entry)" @click="draftTreaty(entry,'我同意与你结盟。')">接受提议</button><button :disabled="treatyUnavailable(entry)" @click="draftTreaty(entry,'我拒绝与你结盟。')">拒绝提议</button></template>
    <button v-else :disabled="treatyUnavailable(entry)" @click="draftTreaty(entry,entry.treaty.status==='PROPOSED'?'我撤回结盟提议。':'我解除与你的盟约。')">{{entry.treaty.status==='PROPOSED'?'撤回提议':'解除盟约'}}</button>
    <p v-if="!people.some(g=>g.godId===entry.treaty.counterpartId)" class="rail-muted">对方不在最近所见人物中。仍可拟定回应，故事会根据实际联系经过与双方意愿继续。</p>
   </div>
  </section>
  <section v-if="visited.length" class="rail-section"><details class="rail-details"><summary>已走过的地方 <small>{{visited.length}}</small></summary><select aria-label="选择已访问地点" :value="selected" :disabled="busy" @change="emit('update:selected',$event.target.value)"><option value="">选择地点</option><option v-for="loc in visited" :key="loc.sceneId" :value="loc.sceneId">{{loc.locationName}}</option></select><div class="rail-location-actions"><button :disabled="busy || !selected" @click="emit('inquire')">打听此处</button><button :disabled="busy || !selected" @click="emit('return')">返回此处</button></div></details></section>
 </div>
</template>
<script setup>
import { computed } from 'vue'
import {storyMoment} from '../utils/storyTime'
import { visibleText, sceneNote, sourceLabel } from '../utils/visibleText'
const props=defineProps({scene:{type:Object,default:()=>({})},busy:Boolean,target:String,selected:String,visited:{type:Array,default:()=>[]},objectives:{type:Array,default:()=>[]},legacyRepair:{type:Object,default:()=>({})},atmosphere:{type:Object,required:true}})
const emit=defineEmits(['talk','exit','share','question','verify','inquire','return','repair-objectives','treaty','update:target','update:selected'])
const people=computed(()=>(props.scene.presentGods || []).filter(g=>g && typeof g==='object' && g.godName))
const treatyUnavailable=entry=>props.busy || !entry.treaty.counterpartId
const draftTreaty=(entry,text)=>{if(!treatyUnavailable(entry))emit('treaty',{targetId:entry.treaty.counterpartId,targetName:entry.treaty.counterpartName || people.value.find(g=>g.godId===entry.treaty.counterpartId)?.godName || '',text})}
const visibleTimeline=computed(()=>(props.scene.eventTimeline || []).filter(event=>event.text && !['本段重要结果，经过见故事正文。','主API本段实际场景结果，经过见故事正文。'].includes(event.text)))
const knownPosition=value=>['原场景位置','当前位置',''].includes(String(value || ''))?'':value
const body=id=>(props.scene.currentPhysicalStates || []).find(p=>p.id===id)
const bodyLabel=id=>{const p=body(id);if(!p)return '入场所见 · 与其交谈';return [Number.isFinite(p.observedAtSeconds)?`${storyMoment(p.observedAtSeconds,{currentSeconds:props.scene.storySeconds,currentLabel:props.scene.storyTime})}所见`:'入场所见',p.awake===false?'意识未恢复':p.awake===true?'清醒':'',p.bound===true?'受束缚':''].filter(Boolean).join(' · ')}
const direction=d=>({NORTH:'北行',SOUTH:'南行',EAST:'东行',WEST:'西行',UP:'向上',DOWN:'向下',OTHER:'前路'}[d] || '前路')
</script>
